(7440262, 1176870, 114285, '<td valign="top">Special shot!</td>', 'Special shot!', '2016-03-01 01:29:46.000000', NULL, 1),
(7440275, 1176433, 113411, '<td valign="top">what a fabulous face..and fabulous shot !!!</td>', 'what a fabulous face..and fabulous shot !!!', '2016-03-01 07:01:23.000000', NULL, 1),
