(7440277, 1175988, 113411, '<td valign="top">fabulous shot!</td>', 'fabulous shot!', '2016-03-01 07:08:29.000000', NULL, 1),
(7440297, 1176589, 30861, '<td valign="top">I used to spend almost every weekend in a small, rundown shack between Hwy 1 and the ocean at Piedras Blancas, about a quarter mile north of the lighthouse. It was owned by Linus Pauling and rented to a friend of mine who was a metal sculptor. So Pedras Blancas calls out to me :-)</td>', 'I used to spend almost every weekend in a small, rundown shack between Hwy 1 and the ocean at Piedras Blancas, about a quarter mile north of the lighthouse. It was owned by Linus Pauling and rented to a friend of mine who was a metal sculptor. So Pedras Blancas calls out to me :-)', '2016-03-01 12:31:26.000000', NULL, 1),
(7440299, 1176578, 30861, '<td valign="top">The birdie "hood ornament" on the front fender is a real double-take moment...</td>', 'The birdie "hood ornament" on the front fender is a real double-take moment...', '2016-03-01 12:33:46.000000', NULL, 1),
(7440300, 1176830, 30861, '<td valign="top">The balance here (of sky and water) is unfortunately a little off, to my taste at least. I''d really like to see 25% less water/more sky, to get more sense of the "arch of heaven". In all other respects, gorgeous and understated.</td>', 'The balance here (of sky and water) is unfortunately a little off, to my taste at least. I''d really like to see 25% less water/more sky, to get more sense of the "arch of heaven". In all other respects, gorgeous and understated.', '2016-03-01 12:36:08.000000', NULL, 1),
(7440301, 1176896, 30861, '<td valign="top">That was a fine escapade, wasn''t it? :-)</td>', 'That was a fine escapade, wasn''t it? :-)', '2016-03-01 12:36:59.000000', NULL, 1),
