(7441859, 1176897, 76335, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by bvy:</b></div><hr/><i> Nice pan. Would have liked a not-so-tight crop across the top. </i></td></tr></table> <br/>Forgive me. I was looking for the top of the street lamp. As such, I perhaps missed what was great about this.</td>', 'Originally posted by bvy: Nice pan. Would have liked a not-so-tight crop across the top.  Forgive me. I was looking for the top of the street lamp. As such, I perhaps missed what was great about this.', '2016-03-08 08:40:05.000000', NULL, 0),
(7441862, 1176583, 60047, '<td valign="top">This is a great shot!<br/></td>', 'This is a great shot!', '2016-03-08 08:45:50.000000', NULL, 0),
(7441869, 1175746, 128323, '<td valign="top">Captivating shot--congrats on the blue Anita!</td>', 'Captivating shot--congrats on the blue Anita!', '2016-03-08 09:11:09.000000', NULL, 0),
(7441870, 1176689, 128323, '<td valign="top">This was my fave of the challenge.  Wonderful composition, congrats on the ribbon!<br/></td>', 'This was my fave of the challenge.  Wonderful composition, congrats on the ribbon!', '2016-03-08 09:11:49.000000', NULL, 0),
(7441872, 1176784, 128323, '<td valign="top">The tones are so great in this--great work in making the contrails add interest and composition to this shot.  Congrats on the TT Jake!</td>', 'The tones are so great in this--great work in making the contrails add interest and composition to this shot.  Congrats on the TT Jake!', '2016-03-08 09:15:13.000000', NULL, 0),
(7441893, 1176553, 101668, '<td valign="top">This is beautiful.</td>', 'This is beautiful.', '2016-03-08 10:16:30.000000', NULL, 0),
(7441894, 1175820, 65234, '<td valign="top">Is that a Yellow-rumped Warbler? I have some at my feeders all of a sudden, and they''re surprisingly terroitorial for such little birds. I love shooting them; they tend to sort of hover in front of the suet feeder and lean in for a bite, showing off their bright yellow rumps. Love your composition here, and of course the detail on the bird.</td>', 'Is that a Yellow-rumped Warbler? I have some at my feeders all of a sudden, and they''re surprisingly terroitorial for such little birds. I love shooting them; they tend to sort of hover in front of the suet feeder and lean in for a bite, showing off their bright yellow rumps. Love your composition here, and of course the detail on the bird.', '2016-03-08 10:17:18.000000', NULL, 0),
(7441895, 1175746, 66641, '<td valign="top">A blue in a free study!!! :D So deserved. :)</td>', 'A blue in a free study!!! :D So deserved. :)', '2016-03-08 10:17:35.000000', NULL, 0),
(7441904, 1175746, 140305, '<td valign="top">Congrats on your first FS blue Anita! Great shot.</td>', 'Congrats on your first FS blue Anita! Great shot.', '2016-03-08 11:11:28.000000', NULL, 0),
(7441906, 1176886, 101668, '<td valign="top">Magnificent</td>', 'Magnificent', '2016-03-08 11:19:51.000000', NULL, 0);
