(7441921, 1176896, 50641, '<td valign="top">Congrats - must have been very exciting!  I like the colors and the way his head is still and focused while everything else is in motion.  <br/></td>', 'Congrats - must have been very exciting!  I like the colors and the way his head is still and focused while everything else is in motion.  ', '2016-03-08 12:22:40.000000', NULL, 0),
(7441950, 1175746, 109227, '<td valign="top">The processing really makes this pop and then the sweet bow in the lips ties it up with a blue ribbon.  Congrats Anita on a wonderful image.</td>', 'The processing really makes this pop and then the sweet bow in the lips ties it up with a blue ribbon.  Congrats Anita on a wonderful image.', '2016-03-08 13:43:43.000000', NULL, 0),
(7441951, 1176395, 109227, '<td valign="top">Nicely don Rob; beautiful light and shadows.</td>', 'Nicely don Rob; beautiful light and shadows.', '2016-03-08 13:44:10.000000', NULL, 0),
